async function waitFor(fn,message,timeout=45000){const start=Date.now();let last;while(Date.now()-start<timeout){try{last=await fn();if(last)return last;}catch(error){last=error.message;}await sleep(120);}throw new Error(`${message}; last=${String(last)}`);}
