function reviewEnvironmentSource(){return `'use strict';
(function(){
  const accounts=${JSON.stringify(previewAccounts)};
  const query=new URLSearchParams(location.search),requested=query.get('review'),partnerReview=query.get('partner-review');
  if(accounts[requested])localStorage.setItem('taxmate-review-account',requested);
  if(!localStorage.getItem('taxmate-review-account'))localStorage.setItem('taxmate-review-account','pro');
  localStorage.setItem('taxmateuk_analytics_consent','denied');
  window.__taxmateReviewFunctionCalls=[];window.__taxmateReviewFaults={retryJoin:0};
  const originalFetch=window.fetch.bind(window),reply=(status,body)=>Promise.resolve(new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json'}}));
  window.fetch=function(input,init){
    const url=String(input&&input.url||input),match=url.match(/\\/(lookupCompaniesHouse|joinPartnership|redeemPromotion|createCheckoutSession)$/),body=(()=>{try{return JSON.parse(init&&init.body||'{}').data||{};}catch(_){return{};}})();
    if(match){const name=match[1];window.__taxmateReviewFunctionCalls.push({name,data:body,at:Date.now()});
      if(name==='createCheckoutSession')return reply(400,{error:{status:'FAILED_PRECONDITION',message:'Payments are unavailable in local review.',details:{reason:'billing-config'}}});
      if(name==='lookupCompaniesHouse'){
        if(body.companyNumber==='11111111')return reply(200,{result:{status:'found',verificationStatus:'verified',reasonCodes:[],retryable:false,company:{number:'11111111',name:'TOODALOOP LTD',incorporationDate:'2025-12-15',status:'active',type:'ltd',registryUrl:'https://find-and-update.company-information.service.gov.uk/company/11111111'}}});
        if(body.companyNumber==='22222222')return reply(200,{result:{status:'not_found',companyNumber:'22222222',reasonCode:'company_not_found',retryable:false}});
        if(body.companyNumber==='33333333')return reply(400,{error:{status:'UNAVAILABLE',message:'Companies House is temporarily unavailable.',details:{reason:'companies_house_temporarily_unavailable',retryable:true}}});
      }
      if(name==='joinPartnership'){
        if(body.code==='UNAVAIL8')return reply(400,{error:{status:'UNAVAILABLE',message:'Partner Sync is temporarily unavailable.',details:{reason:'unavailable'}}});
        if(body.code==='EXPIRED8')return reply(400,{error:{status:'FAILED_PRECONDITION',message:'This Partner Sync code is no longer available.',details:{reason:'expired'}}});
        if(body.code==='RETRY888'&&window.__taxmateReviewFaults.retryJoin++===0)return reply(400,{error:{status:'UNAVAILABLE',message:'Partner Sync is temporarily unavailable.',details:{reason:'unavailable'}}});
      }
      if(name==='redeemPromotion'&&body.code==='UNAVAILABLE')return reply(400,{error:{status:'UNAVAILABLE',message:'Promotion access is temporarily unavailable.',details:{reason:'unavailable'}}});
    }
    return originalFetch(input,init);
  };
  const firebaseInit=firebase.initializeApp.bind(firebase);
  firebase.initializeApp=function(config,name){const app=firebaseInit(config,name),auth=firebase.auth(app);auth.useEmulator('http://127.0.0.1:9099',{disableWarnings:true});firebase.firestore(app).useEmulator('127.0.0.1',8080);firebase.storage(app).useEmulator('127.0.0.1',9199);return app;};
  firebase.appCheck=function(){return{activate:function(){},getToken:async function(){return{token:'emulator-app-check'};}};};
  async function patchAuth(){await ensureFB();const auth=firebase.auth();if(auth.__taxmateReviewPatched)return;auth.__taxmateReviewPatched=true;auth.signInWithPopup=async function(){window.__taxmatePopupCalls=(window.__taxmatePopupCalls||0)+1;const selected=localStorage.getItem('taxmate-review-account')||'pro',preset=accounts[selected]||accounts.pro,email=localStorage.getItem('taxmate-review-email')||preset.email,pass=localStorage.getItem('taxmate-review-password')||preset.password;return auth.signInWithEmailAndPassword(email,pass);};}
  async function reset(mode){const selected=accounts[mode]?mode:'pro',response=await fetch('/__review/reset?mode='+encodeURIComponent(selected),{method:'POST'});if(!response.ok)throw new Error('Local review reset failed: '+response.status);try{await ensureFB();await firebase.auth().signOut();}catch(_){}localStorage.clear();sessionStorage.clear();localStorage.setItem('taxmate-review-account',selected);localStorage.setItem('taxmateuk_analytics_consent','denied');location.assign('/?review='+selected);}
  async function openPartnerReview(entry){const selected=entry==='signed-in-pro'?'proFresh':'free',response=await fetch('/__review/reset?mode='+encodeURIComponent(selected),{method:'POST'});if(!response.ok)throw new Error('Local Partner review reset failed: '+response.status);try{await ensureFB();await firebase.auth().signOut();}catch(_){}localStorage.clear();sessionStorage.clear();localStorage.setItem('taxmate-review-account',selected);localStorage.setItem('taxmateuk_analytics_consent','denied');location.assign('/?review='+encodeURIComponent(selected)+'&partner-review='+encodeURIComponent(entry));}
  async function preparePartnerReview(){if(!partnerReview)return;await ensureFB();const auth=firebase.auth();await new Promise(resolve=>{let unsubscribe=()=>{};unsubscribe=auth.onAuthStateChanged(()=>{unsubscribe();resolve();});});if(auth.currentUser)await auth.signOut();startOnboarding();if(partnerReview==='signed-out')return;const selected=partnerReview==='signed-in-pro'?'proFresh':'free';localStorage.setItem('taxmate-review-account',selected);await obSignIn();}
  window.TaxMateLocalBillingReview=Object.freeze({enabled:true,async purchasePro(input){const mode=localStorage.getItem('taxmate-review-account')||'free',response=await fetch('/__review/purchase?mode='+encodeURIComponent(mode),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cadence:input&&input.cadence||'monthly'})});if(!response.ok)return{status:'failure'};return response.json();}});
  function toolbar(){const box=document.createElement('details');box.id='taxmate-review-controls';box.style.cssText='position:fixed;z-index:12000;inset-block-end:84px;inset-inline-end:8px;background:#fff;color:#182820;border:1px solid #0c8f70;border-radius:12px;padding:6px 8px;font:12px/1.4 system-ui;box-shadow:0 4px 16px #0003;max-width:min(300px,calc(100vw - 16px));max-height:calc(100vh - 110px);overflow:auto';box.innerHTML='<summary style="cursor:pointer;font-weight:800;min-height:32px;display:flex;align-items:center">Review</summary><div style="display:grid;gap:6px;margin-top:8px"><strong>Partner recipient starting state</strong><button data-partner-review="signed-out">Signed out · show sign-in gate</button><button data-partner-review="signed-in-free">Signed in Free · show Pro gate</button><button data-partner-review="signed-in-pro">Signed in Pro · manual code</button><small>No URL carries a Partner code. Choose “Enter a Partner Sync code” and type it manually.</small><hr><button data-review="sole">Reset · Self-employed only</button><button data-review="mixed">Reset · Mixed personal + Ltd</button><button data-review="ltdOnly">Reset · Ltd only</button><button data-review="assistant">Reset · Assistant tasks</button><button data-review="pro">Reset · Pro full workspace</button><button data-review="proFresh">Reset · Pro fresh onboarding</button><button data-review="free">Reset · Free next sign-in</button><button data-review="promo">Reset · Promo next sign-in</button><button data-review-open>Open onboarding</button><small>Local emulators only. No payment or production request.</small></div>';box.querySelectorAll('button').forEach(button=>{button.style.minHeight='44px';});box.querySelectorAll('[data-review]').forEach(button=>button.onclick=()=>reset(button.dataset.review));box.querySelectorAll('[data-partner-review]').forEach(button=>button.onclick=()=>openPartnerReview(button.dataset.partnerReview));box.querySelector('[data-review-open]').onclick=()=>startOnboarding();document.body.appendChild(box);}
  window.TaxMateOnboardingReview=Object.freeze({accounts,patchAuth,reset,openPartnerReview});
  document.addEventListener('DOMContentLoaded',()=>{patchAuth().then(preparePartnerReview).catch(console.error);toolbar();});
})();
`;}

function prepareArtifact(){
  const build=spawnSync(process.execPath,['scripts/build-hosting.js','production','onboarding-connected-review'],{cwd:root,stdio:'inherit'});if(build.status!==0)throw new Error('Onboarding actual-app Hosting artifact build failed');
  const firebaseFiles=['firebase-app-compat.js','firebase-auth-compat.js','firebase-firestore-compat.js','firebase-storage-compat.js','firebase-app-check-compat.js'],vendor=path.join(artifact,'vendor','firebase');fs.mkdirSync(vendor,{recursive:true});for(const file of firebaseFiles)fs.copyFileSync(path.join(root,'node_modules','firebase',file),path.join(vendor,file));
  const htmlPath=path.join(artifact,'index.html');let html=fs.readFileSync(htmlPath,'utf8');for(const file of firebaseFiles)html=html.replace(new RegExp(`https://www\\.gstatic\\.com/firebasejs/[^"']+/${file}`,'g'),`vendor/firebase/${file}`);html=html.replace(/<script[^>]+https:\/\/cdnjs\.cloudflare\.com[\s\S]*?<\/script>\s*/gi,'').replace(/<link[^>]+https:\/\/fonts\.(?:googleapis|gstatic)\.com[^>]*>\s*/gi,'').replace(/<noscript><link[^>]+https:\/\/fonts\.googleapis\.com[^>]*><\/noscript>\s*/gi,'');fs.writeFileSync(htmlPath,html);
  fs.writeFileSync(path.join(artifact,'firebase-environment.js'),`'use strict';\nwindow.TAXMATE_FIREBASE_ENVIRONMENT=Object.freeze({firebaseConfig:Object.freeze({apiKey:'demo-api-key',authDomain:'demo-taxmate.firebaseapp.com',projectId:'demo-taxmate',storageBucket:'demo-taxmate.appspot.com',messagingSenderId:'100000000000',appId:'1:100000000000:web:onboarding-review'}),hosts:Object.freeze(['127.0.0.1','localhost']),appCheckKey:'demo-only',functionsOrigin:'http://127.0.0.1:5001',localReview:true});\n${reviewEnvironmentSource()}`);
  fs.writeFileSync(path.join(artifact,'src','app','sentry-bootstrap.js'),`'use strict';\nwindow.__TAXMATE_SENTRY_STATE__=Object.freeze({enabled:false,reason:'localhost_founder_review',sdkRequested:false});\n`);
}

async function createUser(email){const response=await fetch('http://127.0.0.1:9099/identitytoolkit.googleapis.com/v1/accounts:signUp?key=demo-api-key',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password,returnSecureToken:true})});if(!response.ok)throw new Error(await response.text());return{...(await response.json()),email,password};}
async function adminSet(pathName,value){await testEnv.withSecurityRulesDisabled(async context=>firestore.setDoc(firestore.doc(context.firestore(),...pathName.split('/')),value));}
async function adminGet(pathName){let value=null;await testEnv.withSecurityRulesDisabled(async context=>{const snap=await firestore.getDoc(firestore.doc(context.firestore(),...pathName.split('/')));value=snap.exists()?snap.data():null;});return value;}
async function adminDelete(pathName){await testEnv.withSecurityRulesDisabled(async context=>firestore.deleteDoc(firestore.doc(context.firestore(),...pathName.split('/'))));}
async function collectionRows(pathName){let rows=[];await testEnv.withSecurityRulesDisabled(async context=>{const snap=await firestore.getDocs(firestore.collection(context.firestore(),...pathName.split('/')));rows=snap.docs.map(doc=>({id:doc.id,data:doc.data()}));});return rows;}
async function deleteCollection(pathName){for(const row of await collectionRows(pathName))await adminDelete(`${pathName}/${row.id}`);}
async function storageRows(prefix=''){if(!firebaseAdmin.apps.length)firebaseAdmin.initializeApp({projectId:'demo-taxmate',storageBucket:'demo-taxmate.appspot.com'});const [files]=await firebaseAdmin.storage().bucket('demo-taxmate.appspot.com').getFiles({prefix});return files.map(file=>file.name).sort();}
async function accountCloudSnapshot(uid){const meta=await adminGet(`users/${uid}/app/meta`),entries=await collectionRows(`users/${uid}/entries`),storage=await storageRows(`receipts/${uid}/`);return{meta,entries:entries.sort((a,b)=>a.id.localeCompare(b.id)),storage};}
const entitlement=tier=>tier==='pro'?{subscriptionStatus:'active',paidTier:'pro',billingCadence:'monthly',currentPeriodEnd:Date.now()+365*86400000,serverVerifiedAt:Date.now()}:{subscriptionStatus:'inactive',paidTier:'free',serverVerifiedAt:Date.now()};
async function seedTier(user,tier){await adminSet(`users/${user.localId}/entitlements/current`,entitlement(tier));}
async function seedPromotions(){const now=Date.now(),base={tier:'pro',startsAt:now-60000,maxRedemptions:100,active:true,redemptionCount:0,createdAt:now-60000};await adminSet('founderPromotions/PROREVIEW',{...base,code:'PROREVIEW',permanent:true});await adminSet('founderPromotions/EXPIREDPRO',{...base,code:'EXPIREDPRO',expiresAt:now-1000,permanent:false});await adminSet('founderPromotions/USEDPRO',{...base,code:'USEDPRO',permanent:true});}
async function seedUsedPromotion(user){await adminSet(`promotionRedemptions/USEDPRO__${user.localId}`,{uid:user.localId,code:'USEDPRO',promoCode:'USEDPRO',grantedTier:'pro',redeemedAt:Date.now()-1000,status:'active'});}
async function seedPartnership(code,bizId,name){await adminSet(`partnerships/${code}`,{bizId,name,structure:'partnership',createdBy:'local-review-owner',createdAt:Date.now(),v:1});await adminSet(`partnerships/${code}/members/local-review-owner`,{uid:'local-review-owner',role:'owner',joinedAt:Date.now()});}
async function seedLtdCloud(user,state){const profiles=state.domain&&state.domain.companyProfiles||[],active=profiles.find(item=>item.deletedAt==null);if(!active)return;const companyIds=new Set(state.domain.entities.filter(item=>item.type==='limited_company'&&item.deletedAt==null).map(item=>item.id)),records=LtdSync.recordsForSync(state);for(const collection of LtdSync.COLLECTIONS)for(const record of records[collection]){const envelope=LtdSync.envelope(collection,record,LtdSync.companyIdForRecord(collection,record,companyIds));await adminSet(`users/${user.localId}/ltd/v1/${collection}/${envelope.documentId}`,envelope);}await adminSet(`users/${user.localId}/ltdControl/activeCompany`,{schemaVersion:1,status:'active_slot_claimed',activeCompanyId:active.entityId,accountOwnerUid:user.localId,releasePolicy:'founder_approval_required',claimedAt:Date.now(),updatedAt:Date.now()});}
async function seedReviewDataset(user,state){const now=Date.now(),meta={businesses:state.businesses,businessTombstones:state.businessTombstones||[],folders:state.folders||[],folderTombstones:state.folderTombstones||[],customCats:state.customCats||{},activeCats:state.activeCats||{},yearData:state.yearData||{},settings:{lang:'en',theme:'auto'},metaVersions:state.metaVersions||{},updatedAt:Number(state.metaUpdatedAt)||now,deviceId:'founder-review-seed'};await adminSet(`users/${user.localId}/app/meta`,meta);for(const entry of state.entries||[])await adminSet(`users/${user.localId}/entries/${entry.id}`,entry);await seedLtdCloud(user,state);}
function soleReviewState(){return personalState([{id:'review-sole',name:'Founder Review Trade',structure:'sole'}],[{id:'sole-income',bizId:'review-sole',kind:'income',date:'2026-08-20',amount:2400,cat:'sales',desc:'Client work'},{id:'sole-expense',bizId:'review-sole',kind:'expense',date:'2026-08-21',amount:400,pct:100,cat:'other',desc:'Business costs'}]);}
function ltdOnlyReviewState(){const state=clone(reviewFullState);state.businesses=[];state.entries=[];state.tombstones=[];state.businessTombstones=[];state.yearData={};return state;}
async function assistantReviewState(){const fixture=make('fresh');await fixture.driver.chooseBusinessCategory({category:'limited_company'});const state=clone(fixture.driver.state),personal=personalState([{id:'assistant-trade',name:'Assistant Review Trade',structure:'sole'}],[{id:'assistant-required',bizId:'assistant-trade',kind:'expense',date:'2026-08-19',amount:0,pct:100,cat:'other',desc:'Amount to check'},{id:'assistant-income-date',bizId:'assistant-trade',kind:'income',date:'2026-08-20',dateTBC:true,amount:120,cat:'sales',desc:'Estimated delivery income'},{id:'assistant-expense-date',bizId:'assistant-trade',kind:'expense',date:'2026-08-21',dateTBC:true,amount:45,pct:100,cat:'travel',desc:'Estimated fuel cost'},{id:'assistant-receipt-1',bizId:'assistant-trade',kind:'expense',date:'2026-08-22',amount:12,pct:100,cat:'other',desc:'Parking'},{id:'assistant-receipt-2',bizId:'assistant-trade',kind:'expense',date:'2026-08-23',amount:18,pct:100,cat:'other',desc:'Supplies'}]);state.businesses=personal.businesses;state.entries=personal.entries;state.tombstones=[];state.businessTombstones=[];state.year='2026-27';state.yearData={};state.settings={...state.settings,lang:'en',theme:'auto'};state.domain.companyProfiles=state.domain.companyProfiles.map(profile=>CompanyProfile.normalize(profile));return StateSchema.migrate(state,Date.now(),'assistant-founder-review');}
async function datasetForMode(mode){if(mode==='pro'||mode==='mixed')return clone(reviewFullState);if(mode==='sole')return soleReviewState();if(mode==='ltdOnly')return ltdOnlyReviewState();if(mode==='assistant')return assistantReviewState();return null;}
async function resetReviewAccount(mode){const user=reviewUsers[mode];if(!user)return;await deleteCollection(`users/${user.localId}/entries`);for(const collection of LtdSync.COLLECTIONS)await deleteCollection(`users/${user.localId}/ltd/v1/${collection}`);for(const pathName of [`users/${user.localId}/app/meta`,`users/${user.localId}/ltdControl/activeCompany`,`promotionRedemptions/PROREVIEW__${user.localId}`])await adminDelete(pathName).catch(()=>{});for(const code of ['CONNECT8','RETRY888'])await adminDelete(`partnerships/${code}/members/${user.localId}`).catch(()=>{});const proModes=new Set(['pro','proFresh','sole','mixed','ltdOnly','assistant']);await seedTier(user,proModes.has(mode)?'pro':'free');const dataset=await datasetForMode(mode);if(dataset)await seedReviewDataset(user,dataset);if(mode==='promo'){await adminSet('founderPromotions/PROREVIEW',{...(await adminGet('founderPromotions/PROREVIEW')),redemptionCount:0});}await seedUsedPromotion(user);}

function startServer(){const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.png':'image/png','.ico':'image/x-icon','.svg':'image/svg+xml','.xml':'application/xml','.txt':'text/plain; charset=utf-8'};server=http.createServer(async(req,res)=>{const parsed=new URL(req.url,origin);if(parsed.pathname==='/__review/reset'&&req.method==='POST'){try{await resetReviewAccount(parsed.searchParams.get('mode'));res.writeHead(204);res.end();}catch(error){res.writeHead(500,{'content-type':'text/plain'});res.end(error.message);}return;}if(parsed.pathname==='/__review/purchase'&&req.method==='POST'){try{const mode=parsed.searchParams.get('mode'),user=reviewUsers[mode];if(!user)throw new Error('Unknown review account');await seedTier(user,'pro');res.writeHead(200,{'content-type':'application/json','cache-control':'no-store'});res.end(JSON.stringify({status:'ok',tier:'pro',provider:'localhost_review'}));}catch(error){res.writeHead(400,{'content-type':'application/json'});res.end(JSON.stringify({status:'failure'}));}return;}const relative=decodeURIComponent(parsed.pathname==='/'?'/index.html':parsed.pathname).replace(/^\/+/,''),target=path.resolve(artifact,relative);if(!target.startsWith(path.resolve(artifact)+path.sep)||!fs.existsSync(target)){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'Content-Type':mime[path.extname(target)]||'application/octet-stream','Cache-Control':'no-store'});fs.createReadStream(target).pipe(res);});return new Promise((resolve,reject)=>{server.once('error',reject);server.listen(4180,'127.0.0.1',resolve);});}

async function installNetworkGuard(context){await context.route('**/*',async route=>{const url=route.request().url(),browserOfflineProbe=/^https:\/\/www\.google\.com\/images\/cleardot\.gif(?:\?|$)/.test(url),external=/^https?:\/\//i.test(url)&&!/^http:\/\/(?:127\.0\.0\.1|localhost)(?::\d+)?\//i.test(url);if(browserOfflineProbe){await route.abort('blockedbyclient');return;}if(external&&/(?:sentry|ingest\.)/i.test(url)){sentryRequests.push(url);await route.abort('blockedbyclient');return;}if(external){externalRequests.push(url);await route.abort('blockedbyclient');return;}await route.continue();});}
async function launch(name,{account=null,state=null,viewport={width:390,height:844},headless=true,url='/',preserveLocal=false}={}){const profile=path.join(profileRoot,name),context=await chromium.launchPersistentContext(profile,{headless,executablePath:chromePath(),viewport,serviceWorkers:'allow'});contexts.add(context);context.on('close',()=>contexts.delete(context));await installNetworkGuard(context);await context.addInitScript(({account,state,preserveLocal})=>{if(!sessionStorage.getItem('taxmate-review-test-init')){if(!preserveLocal)localStorage.clear();sessionStorage.setItem('taxmate-review-test-init','1');localStorage.setItem('taxmateuk_analytics_consent','denied');if(account){localStorage.setItem('taxmate-review-account',account.mode||'pro');localStorage.setItem('taxmate-review-email',account.email);localStorage.setItem('taxmate-review-password',account.password);}if(state){localStorage.setItem('taxmateuk_account_v1:local:canonical',JSON.stringify(state));localStorage.setItem('taxmateuk_account_v1:local:onboarding-done','1');}}},{account,state,preserveLocal});const page=context.pages()[0]||await context.newPage();page.on('pageerror',error=>consoleErrors.push(error.message));page.on('console',message=>{if(message.type()==='error'&&!/(?:ERR_FAILED|ERR_BLOCKED_BY_CLIENT|Failed to load resource|status of 403)/.test(message.text()))consoleErrors.push(message.text());});page.on('response',response=>{if(response.status()>=400&&!response.url().includes('/joinPartnership')&&!response.url().includes('/redeemPromotion')&&!response.url().includes('/lookupCompaniesHouse')&&!response.url().includes('/createCheckoutSession'))networkFailures.push({url:response.url(),status:response.status()});});await page.goto(origin+url,{waitUntil:'domcontentloaded',timeout:30000});await page.waitForFunction(()=>typeof window.ensureFB==='function'&&window.TaxMateLtdProductionAdapter&&TaxMateLtdProductionAdapter.isReady()&&window.TaxMateOnboardingReview,null,{timeout:30000});return{context,page};}
async function closeApp(app){if(app&&app.context)await app.context.close();}
async function waitOnboarding(page,heading){try{await page.locator('#ob-root.active').waitFor({timeout:30000});if(heading)await page.getByRole('heading',{name:heading,exact:true}).waitFor();}catch(error){const diagnostic=await page.evaluate(()=>({ob:typeof OB==='undefined'?null:OB&&{screen:OB.screen,loggedIn:OB.loggedIn,signingIn:OB._signingInFlow,pendingSource:OB.pendingIntent&&OB.pendingIntent.source},scope:typeof ACTIVE_ACCOUNT_SCOPE==='undefined'?null:ACTIVE_ACCOUNT_SCOPE&&ACTIVE_ACCOUNT_SCOPE.kind,user:!!(firebase.auth().currentUser&&!firebase.auth().currentUser.isAnonymous),hydration:typeof CLOUD==='undefined'?null:CLOUD.hydrationState,businesses:typeof S==='undefined'?null:S.businesses.length,rootActive:document.getElementById('ob-root')&&document.getElementById('ob-root').classList.contains('active')}));throw new Error(`${error.message}; onboarding=${JSON.stringify(diagnostic)}`);}}
async function startWithoutAccount(page){await waitOnboarding(page);await page.getByRole('button',{name:/Start without an account/i}).click();await waitOnboarding(page,'How would you like to get started?');}
async function productSignIn(page){await page.getByRole('button',{name:/^Sign in/}).click();await page.waitForFunction(()=>firebase.auth().currentUser&&!firebase.auth().currentUser.isAnonymous,null,{timeout:30000});}
async function signedInEntry(page){await waitOnboarding(page);await productSignIn(page);await waitOnboarding(page,'How would you like to get started?');}
async function authOnceThreeSessions(users){
  const sessions=[];
  for(let index=0;index<users.length;index++){
    const app=await launch(`auth-once-${index+1}`,{account:{...users[index],mode:'pro'}});
    try{
      await waitOnboarding(app.page);await app.page.evaluate(()=>TaxMateOnboardingReview.patchAuth());
      const button=app.page.getByRole('button',{name:/^Sign in/});await button.evaluate(node=>{node.click();node.click();node.click();});
      await waitOnboarding(app.page,'How would you like to get started?');
      const facts=await app.page.evaluate(()=>({popupCalls:window.__taxmatePopupCalls||0,authenticated:!!(firebase.auth().currentUser&&!firebase.auth().currentUser.isAnonymous),scopeKind:ACTIVE_ACCOUNT_SCOPE&&ACTIVE_ACCOUNT_SCOPE.kind,scopeMatches:!!(firebase.auth().currentUser&&ACTIVE_ACCOUNT_SCOPE&&ACTIVE_ACCOUNT_SCOPE.uid===firebase.auth().currentUser.uid),transitionPending:ACCOUNT_TRANSITION_PENDING,hydration:CLOUD.hydrationState,ui:ACCOUNT_UI_READY.state,onboardingRoots:document.querySelectorAll('#ob-root').length,activeOnboardingRoots:document.querySelectorAll('#ob-root.active').length}));
      equal(facts.popupCalls,1,`auth session ${index+1}: repeated taps produce one popup request`);equal(facts.authenticated,true,`auth session ${index+1}: first attempt authenticates`);equal(facts.scopeKind,'firebase',`auth session ${index+1}: callback activates Firebase scope`);equal(facts.scopeMatches,true,`auth session ${index+1}: active scope matches the authenticated account`);equal(facts.transitionPending,false,`auth session ${index+1}: account transition completes`);equal(facts.hydration,'converged',`auth session ${index+1}: hydration converges without retry`);equal(facts.ui,'onboarding',`auth session ${index+1}: routing presents the single expected onboarding destination`);equal(facts.onboardingRoots,1,`auth session ${index+1}: exactly one onboarding root exists`);equal(facts.activeOnboardingRoots,1,`auth session ${index+1}: exactly one onboarding root is active`);
      const screenshot=`auth-once-session-${index+1}.png`;await app.page.screenshot({path:path.join(evidence,screenshot),fullPage:true});screenshots.push(screenshot);sessions.push({session:index+1,popupCalls:facts.popupCalls,hydration:facts.hydration,ui:facts.ui,scopeMatched:facts.scopeMatches});
    }finally{await closeApp(app);}
  }
  return sessions;
}
async function enterPartnerCode(page,code){await page.getByRole('button',{name:/Enter a Partner Sync code/i}).click();await waitOnboarding(page,'Enter your Partner Sync code');await page.locator('#ob-partner-code').fill(code);await page.getByRole('button',{name:'Continue',exact:true}).click();}
async function membershipCount(code,uid){return (await collectionRows(`partnerships/${code}/members`)).filter(row=>row.id===uid).length;}
async function currentOb(page){return page.evaluate(()=>eval('OB?JSON.parse(JSON.stringify(OB)):null'))}
async function functionCalls(page,name,code=null){return page.evaluate(({name,code})=>(window.__taxmateReviewFunctionCalls||[]).filter(row=>row.name===name&&(!code||row.data.code===code)).length,{name,code});}
async function route(page){return page.evaluate(()=>TaxMateLtdUIFacade.getSnapshot().navigation.routes.at(-1).screenId);}

async function signedOutLtdResume(user){const app=await launch('signed-out-ltd',{account:{...user,mode:'pro'}});try{await startWithoutAccount(app.page);await app.page.getByRole('button',{name:/Set up a Limited Company/i}).click();await app.page.getByRole('button',{name:/I already have a company/i}).click();await waitOnboarding(app.page);await app.page.getByRole('button',{name:/^Sign in/}).waitFor();equal(await app.page.getByText('Sign in to continue setting up your Limited Company.',{exact:true}).count(),1,'Ltd sign-in uses the pending-intent context');equal(await app.page.getByText(/Self-employed bookkeeping/i).count(),0,'Ltd sign-in does not leak self-employed context');equal(await app.page.getByText(/Got a partner sync code/i).count(),0,'Ltd sign-in does not leak Partner Sync context');const pending=await currentOb(app.page);equal(pending.pendingIntent.ltdChoice,'existing','signed-out Ltd keeps the existing-company choice before authentication');await productSignIn(app.page);await app.page.locator('#taxmate-ltd-ui-root:not([hidden])').waitFor({timeout:30000});await waitFor(()=>route(app.page).then(value=>value==='ltd.onboarding.step1'),'signed-out Ltd did not reach canonical Step 1');equal(await route(app.page),'ltd.onboarding.step1','signed-out Ltd resumes directly into canonical Step 1 after Pro hydration');equal((await app.page.getByRole('heading',{name:'Pro required'}).count()),0,'signed-out Pro Ltd does not show the gate');equal(await app.page.getByRole('button',{name:'Yes',exact:true}).getAttribute('aria-pressed'),'true','existing-company intent selects the registered Companies House path');equal(await app.page.getByRole('button',{name:'Check Companies House',exact:true}).count(),1,'existing-company intent exposes the real Companies House action');equal(await adminGet(`users/${user.localId}/ltdControl/activeCompany`),null,'canonical one-Ltd anchor stays unclaimed until Step 1 Continue');}finally{await closeApp(app);}}

